"""Render private editor/embedding receipts, without inferring transcription gold."""
import argparse
import html
import json
from pathlib import Path
import statistics


def report(root,filename='mini-editor-results.html'):
    def load(name):return json.loads((root/name).read_text())
    def esc(value):return html.escape(str(value))
    def table(headers,rows):
        return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    base={m:load(f'results-{m}/summary.json') for m in ('qwen25','qwen3')}
    corpus=load('results-qwen3-corpus/summary.json');order=load('results-qwen3-order/summary.json');order_observation=load('order-observation.json')
    emb=load('embedding-results/recovered-summary.json');observations=load('corpus-rerank-observation.json')
    rows=[]
    for name,s in base.items():
        for mode in ('edit','rank'):
            controls=[x for x in s['rows'] if x['kind']=='synthetic_text_control' and x['mode']==mode]
            rows.append([name,mode,str(sum(x['normalized_equal_reference'] for x in controls))+'/10',str(sum(bool(x['protected_missing']) for x in controls))+'/10',str(sum(x['negative_tokens_before_after'][0]!=x['negative_tokens_before_after'][1] for x in controls))+'/10'])
    sections=['''<header><p class="eyebrow">ЛОКАЛЬНЫЙ ASR · ЭКСПЕРИМЕНТАЛЬНОЕ ДОПОЛНЕНИЕ</p><h1>Мини-редактор не стал решением.</h1><p class="lead">EmbeddingGemma 2 работает с аудио, но её семантическая оценка не защищает точность слов. Qwen3 хорошо прошла простые контроли и провалила проверку независимости от порядка кандидатов.</p></header>
<section class="verdict"><h2>Решение по результатам</h2><ul><li><b>Не включать свободное редактирование</b> Qwen2.5-0.5B или Qwen3-0.6B: наблюдались переводы, пропуски и смысловые изменения.</li><li><b>Не выбирать точную расшифровку одним cosine score</b> EmbeddingGemma 2: удалённое отрицание получило более высокую оценку.</li><li><b>Не использовать генерацию индекса Qwen3 как надёжный reranker</b>: перестановка кандидатов изменила текст в 14/20 случаях.</li><li>Рабочий Parakeet, gateway, словарь и оригинальные WAV этим экспериментом не изменены. Production-переключения и перезапуска не было.</li></ul></section>
<section><h2>Что действительно исполнено</h2><p><b>91 запрос генеративным моделям:</b> 48 в первом сравнении (2 модели × 2 режима × 12 примеров), 23 в корпусном выборе (20 реальных + 3 новых контроля), 20 в парном варианте порядка. Отдельно: 10 текстовых similarity-контролей и 2 целых аудиозаписи для EmbeddingGemma 2. Это разные типы наблюдений, не 103 независимых теста точности.</p><p>Первое сравнение: 10 синтетических текстовых заданий и 2 ранее сохранённых ASR Nbest. Корпусная часть: 20 доступных успешных результатов на момент фиксации манифеста. Позднее другой запуск корпуса добавил ещё запись; здесь она не проверялась. Ошибочные и отсутствующие результаты ASR не заменялись выдуманным текстом.</p></section>
<section><h2>Простые контроли дали ложный оптимизм</h2><p>«Совпадение» ниже означает равенство нормализованных слов подготовленному текстовому эталону. Регистр и пунктуация не учитываются. Это <b>не WER и не точность распознавания аудио</b>. Число отрицаний — грубый индикатор изменения, а не доказательство сохранения смысла.</p>'''+table(['Модель','Режим','Совпадение с эталоном','Пропуск защищённого имени/числа','Изменение числа отрицаний'],rows)+'</section>']
    examples=[]
    for m,id in (('qwen25','numbers'),('qwen25','negation'),('qwen3','unknown_name'),('qwen3','slang'),('qwen25','unfinished')):
        mode='rank' if id=='unfinished' else 'edit';r=next(r for r in base[m]['rows'] if r['id']==id and r['mode']==mode)
        examples.append([m+' / '+mode,r['input'],r['selected_text']])
    sections.append('<section><h2>Наблюдаемые изменения текста</h2>'+table(['Режим','Вход','Результат'],examples)+'</section>')
    sections.append('<section><h2>Порядок кандидатов оказался решающим</h2><p>Модель, prompt, температура 0, seed 42, исходный текст и набор кандидатов не менялись. Отличался только порядок пунктов. В обратном акустическом порядке первый отображённый пункт выбран в 16/20 случаях; в исходном порядке — в 20/20. Итоговая строка изменилась в <b>'+str(order_observation['changed_by_order'])+'/20</b> пар.</p><p>На трёх дополнительных синтетических контролях Qwen3 выбрала правильный вариант 3/3. Это не отменяет измеренной зависимости на реальном Nbest. В корпусной обратной перестановке 14/20 текстов отличались от первого акустического результата: это изменения, а не 14 доказанных ошибок — человеческого эталона нет.</p>'+table(['Пример','Акустический первый вариант','Выбор при обратном порядке'],[[r['id'],r['input'],r['selected']] for r in observations['rows'] if r['id'] in ('c003','c005','c018','c019')])+'</section>')
    for r in emb['rows']:
        ranked=[r['candidates'][i] for i in r['ranking']]
        sections.append('<section><h2>EmbeddingGemma 2 · '+('короткая' if r['id']=='short' else 'длинная')+' запись</h2><p>Исходное аудио '+f"{r['duration_s']:.3f}"+' с; только audio forward '+f"{r['audio_forward_s']:.3f}"+' с. Это не полная задержка сервиса и не замер Steam Deck. Полных mel-кадров '+str(r['valid_feature_frames'])+', аудиотокенов '+str(r['audio_placeholder_tokens'])+'.</p>'+table(['Источник кандидата','Cosine · не вероятность','Текст'],[[c['source'],f"{c['cosine']:.6f}",c['text']] for c in ranked])+'</section>')
    sections.append('''<section><h2>Что означает результат EmbeddingGemma 2</h2><p>В длинной записи вариант без первого «не» получил 0.692962 против 0.690761 у исходного ASR. Замена DSH на SSH получила 0.691595. В короткой записи лучшим был кандидат с дополнительным «и» в конце. Значения близки, не откалиброваны и сами по себе не дают уверенности в распознавании.</p><p>Среди десяти текстовых контролей выбран ожидаемый вариант 10/10. Разница между этим результатом и audio→text показывает: текстовая семантическая близость не проверяет слышимость каждого слова. Посторонняя фраза про погоду оценивалась ниже, но это только грубое тематическое разделение на двух записях.</p><p>Модель может быть полезна для поиска релевантного контекста или тематических кандидатов. Такой retrieval-сценарий здесь <b>не проверялся</b>; рекомендация использовать её для автоматической коррекции технических названий не подтверждена.</p></section>''')
    resources=[]
    for label,s in [('Qwen2.5 · 24 запроса',base['qwen25']),('Qwen3 · 24 запроса',base['qwen3']),('Qwen3 · корпус 23 запроса',corpus),('Qwen3 · перестановка 20 запросов',order)]:
        resources.append([label,f"{s['elapsed_s']:.3f}",f"{statistics.median(x['elapsed_s'] for x in s['rows']):.3f}",f"{max(x['rss_bytes'] for x in s['samples'])/1048576:.1f}",f"{min(x['available_bytes'] for x in s['samples'])/1048576:.1f}"])
    sections.append('<section><h2>Ресурсы на локальном CPU-хосте</h2>'+table(['Запуск','Полное время, с','Медиана запроса, с','Пик sampled RSS, MiB','Минимум доступно, MiB'],resources)+'<p>Модели запускались последовательно, по 2 CPU-потока, без GPU. Пики четырёх запусков нельзя складывать как одновременное потребление. Агентские пределы: RSS 3072 MiB для редактора, минимум доступной памяти 2048 MiB, прирост swap не более 256 MiB. Для embedding — RSS 6144 MiB; итоговый RSS не сохранился.</p><p><b>Технический предел доказательств:</b> оба embedding inference завершились, но общий JSON-итог сломался при сериализации множества в loading_info (exit 1). Отдельные результаты и векторы сохранены, восстановленный итог собран из них. Общие wall time, peak RSS и полный loading_info этого запуска отсутствуют; они не восстановлены предположением. Повторного inference ради красивого отчёта не было. Исправление сериализации добавлено для следующих запусков.</p></section>')
    sections.append('''<section><h2>Воспроизводимость и ограничения</h2><ul><li>Qwen2.5 официальный Q8_0: revision 9217f5db79a29953eb74d5343926648285ec7e67; фактический GGUF tensor count 630167424. Qwen3 официальный Q8_0: revision 23749fefcc72300e3a2ad315e1317431b06b590a; tensor count 596049920. Оба меньше 1B.</li><li>llama.cpp b11429, native Jinja, контекст 4096, greedy temperature 0, top_p 1, repeat penalty 1, seed 42, Qwen3 enable_thinking=false. Сохранены server props/template, model metadata, payload, response, finish reason и временные замеры. Сохранён шаблон, не отдельная строка каждого полностью отрендеренного prompt.</li><li>EmbeddingGemma 2: revision 914f7f89142e33e77833254d9c9b90c3cef7303b, полный checkpoint 744371512 параметров. Без vision tower заявленная загрузка text+audio около 570M; точный локальный параметр-count не сохранился. FP32 CPU, Transformers 5.19.0, Torch 2.8.0 CPU. Маскированное среднее, L2-нормализация, 768D, опубликованный SentenceSimilarity prefix только на тексте.</li><li>Изолированное embedding-окружение: предыдущий Torch 2.5.1 несовместим с новым Transformers; обновлялось только новое окружение. Оригинальное ASR-окружение не менялось.</li><li>Исходный waveform не резался, не дополнялся и не пересэмплировался. В процессоре отключены batch padding и truncation; стандартное внутреннее полукадровое дополнение STFT сохранено как часть модели.</li><li>Первые два ASR Nbest взяты из сохранённого closed-word варианта, не из позднейшего state-forward. Корпусный этап использует более новые сохранённые final receipts. Это разные входные наборы, не сравнение акустических backend на одинаковом корпусе.</li><li>У реальных записей нет проверенного человеческого gold. Архивный production-текст, альтернативный ASR и модельный редактор не считаются эталонами.</li><li>Не проводились обучение, публикация частного аудио/текста, новые акустические прогоны корпуса или переключение production. Все новые текстовые результаты — экспериментальные производные, raw ASR сохранён.</li></ul></section>
<section><h2>Следующий обоснованный шаг</h2><p>Для продолжения задачи нужен критерий, чувствительный к словам и исходному звуку, а не к гладкости текста или порядку списка. Независимый численный score каждого кандидата проверяется отдельным дополнением к этому отчёту; он устраняет список из входа, но не добавляет акустических данных. Следующее содержательное направление — акустическая проверка отличающихся слов в обученных RU/EN heads. Такой новый механизм здесь пока не реализован. Не стоит соединять три провалившихся эвристики и считать их ошибки взаимно компенсированными.</p><p>Общая задача непрерывного точного двуязычного ASR остаётся открытой. Этот отчёт закрывает проверку предложенных дополнений, а не всю задачу.</p></section>
<footer><h2>Первичные источники</h2><p><a href="https://huggingface.co/google/embeddinggemma-2/tree/914f7f89142e33e77833254d9c9b90c3cef7303b">Pinned EmbeddingGemma 2</a> · <a href="https://ai.google.dev/gemma/docs/embeddinggemma/model_card_2?hl=en">Google model card</a> · <a href="https://github.com/ggml-org/llama.cpp/releases/tag/b11429">llama.cpp b11429</a> · <a href="https://huggingface.co/Qwen/Qwen3-0.6B-GGUF">Qwen3 GGUF</a> · <a href="https://huggingface.co/Qwen/Qwen2.5-0.5B-Instruct-GGUF">Qwen2.5 GGUF</a></p><p>Частный отчёт. Расшифровки и результаты не входят в Git.</p></footer>''')
    css='''*{box-sizing:border-box}body{margin:0;background:#f3f0e8;color:#202622;font:17px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:48px 28px}header{padding:32px 0 46px;border-bottom:3px solid #244a3b}h1{font-size:clamp(36px,5vw,66px);line-height:1.08;max-width:860px;letter-spacing:-.04em}h2{font-size:27px;line-height:1.2}p,li{max-width:100ch}.eyebrow{font-size:12px;letter-spacing:.13em;font-weight:800;color:#45634f}.lead{font-size:22px;max-width:760px}section{padding:30px 0;border-bottom:1px solid #c4c8bf}.verdict{border-left:5px solid #b04d32;padding-left:24px;margin-top:30px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th{text-align:left;background:#dfe5dc}th,td{padding:12px;border-bottom:1px solid #c4c8bf;vertical-align:top}td:last-child{min-width:200px}a{color:#235a45}footer{padding:30px 0;font-size:14px}li{margin:9px 0}@media print{body{background:white}main{padding:10px}section{break-inside:avoid}table{font-size:10px}}'''
    if (root/'likelihood-sequential/summary.json').exists():
        from likelihood_report import section
        sections.insert(1,section(root))
    if (root.parent/'routing-repair/round11-results/supervisor-summary.json').exists():
        from routing_repair_report import section as routing_section
        sections.insert(1,routing_section(root))
    if (root.parent/'routing-repair/round12-observation.json').exists():
        from corroborated_report import section as corroborated_section
        sections.insert(1,corroborated_section(root))
        sections[0]='''<header><p class="eyebrow">ЛОКАЛЬНЫЙ RU/EN ASR · РАУНД 12</p><h1>Строгое подтверждение отсекает и нужный английский.</h1><p class="lead">Проверка подсказок по native CTC убрала четыре отказа на повторах, но все 16 изменённых маршрутов стали полностью русскими. Это отрицательный результат для двуязычной задачи, не улучшение точности.</p></header>'''
    if (root.parent/'routing-repair/round13-observation.json').exists():
        from occurrence_report import section as occurrence_section
        sections.insert(1,occurrence_section(root))
        sections[0]='''<header><p class="eyebrow">ЛОКАЛЬНЫЙ RU/EN ASR · РАУНД 13</p><h1>Акустические альтернативы теперь измеряются без top1-фильтра.</h1><p class="lead">Рассчитана масса 133 словесных событий на 28 сохранённых записях. Это новый диагностический инструмент, но ещё не надёжный критерий коррекции: прежние технические названия могут иметь очень малую массу.</p></header>'''
    if (root.parent/'routing-repair/round14-observation.json').exists():
        from qwen_auxiliary_report import section as qwen_auxiliary_section
        sections.insert(1,qwen_auxiliary_section(root))
        sections[0]='''<header><p class="eyebrow">ЛОКАЛЬНЫЙ RU/EN ASR · РАУНД 14</p><h1>Другой источник подсказки; те же обученные RU/EN-головы.</h1><p class="lead">Qwen3-ASR заменяет только вспомогательный Whisper. Сравнены все28 оригиналов, новые языковые маршруты и финальные результаты — без копирования Qwen-текста и без объявления его эталоном.</p></header>'''
    target=root/filename
    with target.open('x') as file:file.write('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Мини-модели и EmbeddingGemma 2 · результаты ASR</title><style>'+css+'</style><main>'+''.join(sections)+'</main></html>')
    return target


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('root',type=Path);p.add_argument('--filename',default='mini-editor-results.html');a=p.parse_args();print(report(a.root,a.filename))
